import heapq
# (링크, 시작 노드, 끝 노드, 길이 m, 일방통행?)
links = [("L1","A","B",400,False),("L2","B","D",300,True),
         ("L3","A","C",350,False),("L4","C","D",500,False)]
def build(rows):
    g = {}
    for _, f, t, m, oneway in rows:
        g.setdefault(f, []).append((t, m))
        if not oneway:
            g.setdefault(t, []).append((f, m))
    return g
def route(g, s, e):
    pq, best, prev = [(0, s)], {s: 0}, {}
    while pq:
        d, u = heapq.heappop(pq)
        if u == e: break
        if d > best[u]: continue
        for v, m in g.get(u, []):
            if d + m < best.get(v, 1e18):
                best[v] = d + m; prev[v] = u; heapq.heappush(pq, (d + m, v))
    path, n = [e], e
    while n != s: n = prev[n]; path.append(n)
    return best[e], path[::-1]
print("일방통행 반영 A→D:", route(build(links), "A", "D"))
print("일방통행 반영 D→A:", route(build(links), "D", "A"))
flat = [(i, f, t, m, False) for i, f, t, m, _ in links]
print("양방향으로 잘못 읽음 D→A:", route(build(flat), "D", "A"))
# 일방통행 반영 A→D: (700, ['A', 'B', 'D'])
# 일방통행 반영 D→A: (850, ['D', 'C', 'A'])
# 양방향으로 잘못 읽음 D→A: (700, ['D', 'B', 'A'])

import heapq
N = 40
blocked = {(20, y) for y in range(5, 40)}  # 가운데 강, 아래 5칸만 다리
def nb(p):
    x, y = p
    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
        q = (x+dx, y+dy)
        if 0 <= q[0] < N and 0 <= q[1] < N and q not in blocked:
            yield q
def search(s, e, h):
    pq, best, settled = [(h(s), 0, s)], {s: 0}, 0
    while pq:
        _, d, u = heapq.heappop(pq)
        if d > best[u]: continue
        settled += 1
        if u == e: return d, settled
        for v in nb(u):
            if d + 1 < best.get(v, 1e9):
                best[v] = d + 1; heapq.heappush(pq, (d+1+h(v), d+1, v))
s, e = (2, 30), (38, 30)
man = lambda p: abs(p[0]-e[0]) + abs(p[1]-e[1])
for name in ("강 있음", "강 없음"):
    print(f"[{name}] 다익스트라", search(s, e, lambda p: 0), "A*", search(s, e, man))
    blocked.clear()
# [강 있음] 다익스트라 (88, 1509) A* (88, 1204)
# [강 없음] 다익스트라 (36, 1050) A* (36, 37)
